let sdk=null,auth=null,loading=null,user=null,state='idle',busy=false,message='',unsubscribe=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function changed(){if(typeof api.onChange==='function')api.onChange();}
function errorText(e){return ({'auth/popup-closed-by-user':'Login dibatalkan. Kamu bisa mencoba lagi.','auth/cancelled-popup-request':'Selesaikan jendela login yang sudah terbuka.','auth/popup-blocked':'Izinkan popup untuk situs ini, lalu tekan Login lagi. Gunakan Chrome atau browser utama.','auth/unauthorized-domain':'Domain ini belum diizinkan di Firebase Authentication.','auth/operation-not-allowed':'Provider Google belum diaktifkan di Firebase.','auth/network-request-failed':'Koneksi bermasalah. Periksa internet lalu coba lagi.','auth/web-storage-unsupported':'Penyimpanan browser diblokir. Izinkan penyimpanan situs untuk masuk.','auth/invalid-api-key':'Konfigurasi Firebase belum sesuai. Hubungi pengelola.'})[e?.code]||'Akun belum bisa dihubungkan. Periksa koneksi lalu coba lagi.';}
async function loadSDK(){const [app,authSDK]=await Promise.all([import('https://www.gstatic.com/firebasejs/13.2.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/13.2.0/firebase-auth.js')]);return {...app,...authSDK};}
function start(){if(loading)return loading;if(auth&&state==='ready')return Promise.resolve(true);state='loading';message='Menghubungkan akun…';changed();loading=(async()=>{try{sdk=await loadSDK();const app=sdk.getApps().find(a=>a.name==='dex-gaku-auth')||sdk.initializeApp(config,'dex-gaku-auth');auth=sdk.getAuth(app);await sdk.setPersistence(auth,sdk.browserLocalPersistence);if(unsubscribe)unsubscribe();unsubscribe=sdk.onAuthStateChanged(auth,u=>{user=u||null;state='ready';message='';changed();},e=>{user=null;state='error';message=errorText(e);changed();});return true;}catch(e){state='error';message=errorText(e);changed();return false;}finally{loading=null;}})();return loading;}
function signIn(){if(busy)return Promise.resolve(false);if(state!=='ready'||!auth){return start();}busy=true;message='Menunggu pilihan akun Google…';changed();const provider=new sdk.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});let result;try{result=sdk.signInWithPopup(auth,provider);}catch(e){result=Promise.reject(e);}return Promise.resolve(result).then(()=>true,e=>{message=errorText(e);return false;}).finally(()=>{busy=false;if(user)message='';changed();});}
async function signOut(){if(busy||!auth)return false;busy=true;message='Keluar dari akun…';changed();try{await sdk.signOut(auth);user=null;message='Kamu sudah keluar. Data belajar tetap tersimpan di perangkat ini.';return true;}catch(e){message=errorText(e);return false;}finally{busy=false;changed();}}
function photoURL(url){try{const u=new URL(url);return u.protocol==='https:'&&(u.hostname==='googleusercontent.com'||u.hostname.endsWith('.googleusercontent.com'))?u.href:'';}catch{return '';}}
function panel(full=false){const photo=photoURL(user?.photoURL);return `<section class="account-card" aria-label="Akun belajar" aria-busy="${busy||state==='loading'}"><span class="mini-tag">AKUN BELAJAR · ${user?'GOOGLE':'TAMU'}</span>${user?`<div style="display:flex;align-items:center;gap:14px;margin-top:20px;overflow-wrap:anywhere">${photo?`<img src="${esc(photo)}" alt="Foto profil Google" width="56" height="56" referrerpolicy="no-referrer" style="border-radius:50%;object-fit:cover" onerror="this.hidden=true">`:''}<div><h3 style="margin:0">${esc(user.displayName||'Teman belajar')}</h3><p style="margin:4px 0">${esc(user.email||'Akun Google')}</p></div></div><button class="google-button" style="margin-top:20px" onclick="GakuAuth.signOut()" ${busy?'disabled':''}>Keluar dari akun</button>`:`<h3>Belajar bersama akun Google</h3><p>Masuk untuk menghubungkan akun Google dengan DeX Gaku. Kamu tetap bisa belajar sebagai tamu.</p><button class="google-button" onclick="GakuAuth.signIn()" ${busy||state==='loading'?'disabled':''}><span class="google-g" aria-hidden="true">G</span>${state==='idle'||state==='error'?'Hubungkan akun Google':busy?'Menunggu Google…':state==='loading'?'Menyiapkan login…':'Login dengan Google'}</button>`}<p role="status" aria-live="polite" class="hint">${esc(message)}</p><p class="hint">Data belajar tersimpan di perangkat ini. Gunakan Cadangan akun di Pengaturan untuk menyimpan atau mengambil data antarperangkat.</p>${full&&!user?`<button class="chip" onclick="showPage('Pengaturan')">Lanjut sebagai Tamu</button>`:''}</section>`;}
const api={start,signIn,signOut,panel,onChange:null,get user(){return user;},get state(){return state;},get busy(){return busy;},get firebaseApp(){return auth?.app||null;}};w.GakuAuth=api;
